# ==============================================================================# 035_SCHEDULER_ENGINE.py# ==============================================================================import sqlite3from pathlib import Pathfrom datetime import datetime, timedeltaROOT = Path(__file__).resolve().parentDB = ROOT / "MISSION_CONTROL" / "database" / "mission_control.db"conn = sqlite3.connect(DB, timeout=30)conn.row_factory = sqlite3.Rowcur = conn.cursor()

cur.execute("PRAGMA journal_mode=WAL")
cur.execute("PRAGMA synchronous=NORMAL")
cur.execute("PRAGMA busy_timeout=30000")cur.execute("""CREATE TABLE IF NOT EXISTS scheduler(    id INTEGER PRIMARY KEY AUTOINCREMENT,    created_at TEXT,    service TEXT,    frequency_seconds INTEGER,    last_execution TEXT,    next_execution TEXT,    status TEXT)""")conn.commit()SERVICES = [("HEALTH CHECK",300),("OBSERVABILITY",60),("METRICS",60),("EVENT ENGINE",30),("MISSION ENGINE",120),("API CORE",30),("AUDIT",600),("NOTIFICATION",60)]now = datetime.now()for service,frequency in SERVICES:    cur.execute(        "SELECT id FROM scheduler WHERE service=?",        (service,)    )    if cur.fetchone() is None:        cur.execute("""        INSERT INTO scheduler(            created_at,            service,            frequency_seconds,            last_execution,            next_execution,            status        )        VALUES(?,?,?,?,?,?)        """,(            now.isoformat(),            service,            frequency,            now.isoformat(),            (now + timedelta(seconds=frequency)).isoformat(),            "SCHEDULED"        ))conn.commit()cur.execute("""SELECTservice,frequency_seconds,next_execution,statusFROM schedulerORDER BY frequency_seconds""")print("="*80)print("SCHEDULER ENGINE")print("="*80)for row in cur.fetchall():    print(        f"{row['service']:<18}"        f"{row['frequency_seconds']:>5}s   "        f"{row['status']:<10} "        f"{row['next_execution']}"    )print("="*80)cur.execute("SELECT COUNT(*) total FROM scheduler")print("TAREFAS AGENDADAS:", cur.fetchone()["total"])print("="*80)conn.close()

